              origin: 'catalog',
              created: '2025-04-01T10:00:00.000Z',
              payload: {
                title: 'Component entity missing owner',
                severity: 'high',
                link: '/catalog/default/component/my-service',
              },
            },
          ],
          totalCount: 1,
        },
      },
      {
        title: 'Get all notifications from the past week',
        input: {
          view: 'all',
          createdAfter: '2025-04-03T00:00:00Z',
          limit: 25,
        },
      },
